#!/usr/bin/env python3
"""results/gated/*.json -> results/gated/GATED.md"""
import json, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[2]
G = ROOT / "results" / "gated"
L = ["# Gated models", "",
     "Generated by `scripts/gated/gated_report.py`. With a Hugging Face token the account could authenticate, but every",
     "gated repository below answered 403: access requires accepting each publisher's licence on its model page, which",
     "only the account owner can do. What a token does allow is reading file metadata, including the sha256 of every",
     "weight file. That is enough to check that the open copies we used are byte-identical to the official releases.", "",
     "## Open copies vs official releases (sha256 of the weight files)", "",
     "| open copy used | official release | weight files identical | files holding the token vectors identical |", "|---|---|---|---|"]
for r in json.load(open(G / "mirror_hashes_embed.json")):
    if not r.get("official"): continue
    L.append(f"| {r['mirror']} | {r['official']} | {r['safetensors_identical']} / {r['safetensors_official']} | "
             f"{'yes' if r['embedding_files_identical'] else 'no'} |")
L += ["", "Every copy used for Llama 2, 3, 3.1, 3.2, 3.3 and 4 holds byte-identical weight files. The two Llama-3.1-405B",
      "FP8 releases are re-packaged (different files), so their 16-bit token vectors were compared value by value with a copy",
      "whose files are byte-identical to Meta's:", ""]
p = G / "sub405_embed.json"
if p.exists():
    L += ["| copy used | compared with | official release it matches by sha256 | token vectors bit-identical |", "|---|---|---|---|"]
    for r in json.load(open(p)):
        L.append(f"| {r['substitute']} | {r['reference']} | {r['reference_file_sha256_equals']} | "
                 f"{r['identical_rows']:,} / {r['rows']:,} ({'all values' if r['bit_identical'] else str(r['identical_values']) + ' of ' + str(r['values']) + ' values'}) |")
p = ROOT / "results" / "roster" / "sweep_gated.jsonl"
if p.exists():
    L += ["", "## Comparisons now run through a verified open copy", "",
          "| official base | open copy | fine-tune | bit-identical token vectors | shrink factor | fit | share of vectors by fraction of numbers changed (0 / <=1% / 1-10% / 10-50% / >50%) |",
          "|---|---|---|---|---|---|---|"]
    for l in open(p):
        r = json.loads(l); e = r.get("embed", {}); h = r.get("change_hist", {}).get("frac")
        L.append(f"| {r['official_parent']} | {r['mirror_used']} | {r['child']} | {e.get('unmoved', '-')} | {e.get('P', '-')} | "
                 f"{e.get('P_exact_frac', '-')} | {' / '.join(f'{x:.3f}' for x in h) if h else r.get('status')} |")
blocked = json.load(open(G / "blocked.json"))
L += ["", "## Still blocked (licence not accepted on this account)", "",
      "These need the account owner to accept the licence on each model page; nothing else is missing.", ""]
L += [f"- {b['repo']}: {b['needed_for']}" for b in blocked]
(G / "GATED.md").write_text("\n".join(L) + "\n")
print("\n".join(L))
